import{_ as n,o as s,c as t,ah as e}from"./chunks/framework.BTO5-XmS.js";import"./chunks/theme.CryyyygB.js";const k=JSON.parse('{"title":"Agent Engine 代理引擎","description":"Agent 执行引擎——命令编排、工具管理、模型选择、ACP 子代理生成，Agent 的大脑","frontmatter":{"abstract":"OpenClaw Agent Engine 代理引擎的源码解析，讲解 AgentCommand 大脑的核心职责、命令编排流程、工具策略与模型回退机制。","type":"concept","tags":["AI","OpenClaw","Agent","执行引擎"],"domain":"AI","description":"Agent 执行引擎——命令编排、工具管理、模型选择、ACP 子代理生成，Agent 的大脑","created":"2026-09-07T00:00:00.000Z","updated":"2026-09-07T00:00:00.000Z","status":"integrated","source":"[[Resources/人工智能/OpenClaw/核心模块/02-agent-engine]]、[[Resources/人工智能/OpenClaw/核心组件/01-AgentCommand]]","related":["[[🦀 OpenClaw-MOC]]","[[OpenClaw-架构总览]]","[[OpenClaw-LLM-Client]]","[[OpenClaw-Tools-System]]","[[OpenClaw-ACP]]","[[OpenClaw-Context-Engine]]"],"category":["🦀 OpenClaw","基础层"]},"headers":[],"relativePath":"vault/Knowledge/AI/OpenClaw-Agent-Engine.md","filePath":"vault/Knowledge/AI/OpenClaw-Agent-Engine.md","lastUpdated":1793186727000}'),i={name:"vault/Knowledge/AI/OpenClaw-Agent-Engine.md"};function l(p,a,r,d,o,h){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="agent-engine-代理引擎" tabindex="-1">Agent Engine 代理引擎 <a class="header-anchor" href="#agent-engine-代理引擎" aria-label="Permalink to “Agent Engine 代理引擎”">​</a></h1><p><strong>源码路径</strong>：<code>src/agents/</code>（~97 文件） <strong>核心文件</strong>：<code>agent-command.ts</code>（86KB）</p><p>Agent Engine 是 OpenClaw 的执行核心。每次用户消息触发 Agent 运行时，Engine 负责模型选择 → 工具装配 → 上下文注入 → 执行 → 结果交付。</p><h2 id="通俗类比-agentcommand-是「大脑」" tabindex="-1">通俗类比：AgentCommand 是「大脑」 <a class="header-anchor" href="#通俗类比-agentcommand-是「大脑」" aria-label="Permalink to “通俗类比：AgentCommand 是「大脑」”">​</a></h2><p>当用户发消息给 AI 时，AgentCommand 决定：</p><ol><li><strong>用哪个 Agent？</strong> — 默认助手还是代码助手</li><li><strong>用哪个模型？</strong> — GPT-4o、Claude 3.5、Gemini…，支持 fallback</li><li><strong>会话状态在哪？</strong> — 历史消息存在哪个 session 文件</li><li><strong>哪些工具可用？</strong> — 根据配置、插件、权限动态计算</li><li><strong>怎么把回复发出去？</strong> — 调 <code>dispatchReply</code></li></ol><h2 id="核心职责" tabindex="-1">核心职责 <a class="header-anchor" href="#核心职责" aria-label="Permalink to “核心职责”">​</a></h2><table tabindex="0"><thead><tr><th>职责</th><th>说明</th></tr></thead><tbody><tr><td>命令编排</td><td>处理 Agent 命令全生命周期（规范化→模型选择→交付→重试）</td></tr><tr><td>工具管理</td><td>组装核心/Shell/频道/插件/MCP 工具，应用多层策略过滤</td></tr><tr><td>模型选择</td><td>规范化模型引用，自动回退探测</td></tr><tr><td>作用域配置</td><td>管理 Agent 作用域（模型回退、技能、工作区）</td></tr><tr><td>ACP 生成</td><td>生成子代理和 ACP 会话，处理父流绑定</td></tr><tr><td>工具定义适配</td><td>将运行时 AgentTool 适配为 ToolDefinition</td></tr></tbody></table><h2 id="命令编排流程" tabindex="-1">命令编排流程 <a class="header-anchor" href="#命令编排流程" aria-label="Permalink to “命令编排流程”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span>用户消息到达</span></span>
<span class="line"><span>  → normalizeAgentCommandModelRef()  // 规范化模型引用</span></span>
<span class="line"><span>  → hasConfiguredProvider()          // 检查提供商配置</span></span>
<span class="line"><span>  → 解析会话上下文</span></span>
<span class="line"><span>  → buildEffectiveAgentToolSurface() // 构建工具表面</span></span>
<span class="line"><span>  → 注入系统提示词/上下文</span></span>
<span class="line"><span>  → chatCompletion()                 // 调用 LLM</span></span>
<span class="line"><span>  → 处理工具调用结果</span></span>
<span class="line"><span>  → 交付回复</span></span></code></pre></div><h2 id="工具策略系统-多层过滤" tabindex="-1">工具策略系统（多层过滤） <a class="header-anchor" href="#工具策略系统-多层过滤" aria-label="Permalink to “工具策略系统（多层过滤）”">​</a></h2><p>通过多层策略管道控制工具可见性：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span>所有可用工具</span></span>
<span class="line"><span>  → sandbox policy    (沙箱策略过滤)</span></span>
<span class="line"><span>  → profile policy    (配置文件策略过滤)</span></span>
<span class="line"><span>  → provider policy   (提供商策略过滤)</span></span>
<span class="line"><span>  → sender policy     (发送者策略过滤)</span></span>
<span class="line"><span>  → group policy      (组策略过滤)</span></span>
<span class="line"><span>  → sub-agent policy  (子代理策略过滤)</span></span>
<span class="line"><span>  → 最终工具表面</span></span></code></pre></div><p>关键常量：<code>MEMORY_FLUSH_ALLOWED_TOOL_NAMES</code>（允许触发内存刷新的工具白名单）</p><h2 id="模型选择与回退" tabindex="-1">模型选择与回退 <a class="header-anchor" href="#模型选择与回退" aria-label="Permalink to “模型选择与回退”">​</a></h2><div class="language-typescript"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#61AFEF;">normalizeAgentCommandModelRef</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">()      </span><span style="--shiki-light:#6A737D;--shiki-light-font-style:inherit;--shiki-dark:#7F848E;--shiki-dark-font-style:italic;">// 规范化模型引用</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#61AFEF;">hasExactConfiguredProviderModel</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">()    </span><span style="--shiki-light:#6A737D;--shiki-light-font-style:inherit;--shiki-dark:#7F848E;--shiki-dark-font-style:italic;">// 精确匹配</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#61AFEF;">autoFallbackPrimaryProbeStateKey</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">()   </span><span style="--shiki-light:#6A737D;--shiki-light-font-style:inherit;--shiki-dark:#7F848E;--shiki-dark-font-style:italic;">// 主模型探测状态</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#61AFEF;">pruneAutoFallbackPrimaryProbeState</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">() </span><span style="--shiki-light:#6A737D;--shiki-light-font-style:inherit;--shiki-dark:#7F848E;--shiki-dark-font-style:italic;">// 清理过期探测</span></span></code></pre></div><p>主模型不可用时，Engine 记录探测状态并自动切换到回退模型，状态过期后自动清理。</p><h2 id="acp-子代理生成" tabindex="-1">ACP 子代理生成 <a class="header-anchor" href="#acp-子代理生成" aria-label="Permalink to “ACP 子代理生成”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span>acp-spawn.ts</span></span>
<span class="line"><span>  → 创建 ACP 会话标识</span></span>
<span class="line"><span>  → 设置父流绑定</span></span>
<span class="line"><span>  → 应用线程绑定策略</span></span>
<span class="line"><span>  → 注入通道解析上下文</span></span>
<span class="line"><span>  → 返回子代理引用</span></span></code></pre></div><h2 id="设计模式" tabindex="-1">设计模式 <a class="header-anchor" href="#设计模式" aria-label="Permalink to “设计模式”">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>应用</th></tr></thead><tbody><tr><td>策略模式</td><td>工具过滤 pipeline（多层策略）</td></tr><tr><td>适配器模式</td><td>AgentTool → ToolDefinition</td></tr><tr><td>规范化管道</td><td>normalize* 函数族</td></tr><tr><td>子代理生成</td><td>ACP spawn 生命周期管理</td></tr><tr><td>回退探测</td><td>主模型健康状态追踪</td></tr></tbody></table><h2 id="依赖关系" tabindex="-1">依赖关系 <a class="header-anchor" href="#依赖关系" aria-label="Permalink to “依赖关系”">​</a></h2><ul><li><strong>上游</strong>：Auto-Reply（触发引擎执行）</li><li><strong>下游</strong>：LLM Client、Tools System、MCP、Memory、Context Engine</li><li><strong>横切</strong>：Hook System、Session Manager</li></ul>`,23)])])}const b=n(i,[["render",l]]);export{k as __pageData,b as default};
